{"command": "cd /workspace && python3 -c "
import json
d={eval(k):v for k,v in json.load(open('/tmp/ord_data.json')).items()}
def rust_bs(arr, x):
    # returns (found, idx) mimicking Rust slice::binary_search
    n=len(arr)
    if n==0: return (False,0)
    base=0; size=n
    while size>1:
        half=size//2
        mid=base+half
        if arr[mid]>x:
            base=base
        else:
            base=mid
        size-=half
    c=arr[base]
    if c==x: return (True,base)
    return (False, base + (1 if c<x else 0))
ok=0; bad=[]
for (L,x),out in sorted(d.items()):
    base=[int(c) for c in L.split(',')]
    b2=[f for f in base if f!=x]
    found,idx=rust_bs(base,x)
    pred = b2[:idx]+[x]+b2[idx:]
    if pred==out: ok+=1
    else: bad.append((L,x,out,pred,found,idx))
print('match',ok,'of',len(d))
for b in bad: print(b)
""}

