import json,re
cases=json.load(open('/tmp/hf_cases.json'))
def rust_bs(arr,x):
    n=len(arr)
    if n==0: return (False,0)
    base=0; size=n
    while size>1:
        half=size//2; mid=base+half
        base = base if arr[mid]>x else mid
        size-=half
    c=arr[base]
    if c==x: return (True,base)
    return (False, base+(1 if c<x else 0))
def sim(gs, posfn):
    lst=[]
    for g in gs:
        for f in sorted(g):
            if f in lst: continue
            p=min(posfn(lst,f), len(lst))
            lst.insert(p,f)
    return lst
cands={}
cands['seq']=lambda lst,f: len(lst)
cands['count_lt']=lambda lst,f: sum(1 for y in lst if y<f)
cands['count_le']=lambda lst,f: sum(1 for y in lst if y<=f)
cands['bs']=lambda lst,f: rust_bs(lst,f)[1]
cands['first_ge']=lambda lst,f: next((i for i,y in enumerate(lst) if y>=f), len(lst))
for name,fn in cands.items():
    ok=0; bad=[]
    for k,gs,idx in cases:
        pr=sim(gs,fn)
        # dedup? keep duplicates
        if pr==idx: ok+=1
        else: bad.append((k,gs,idx,pr))
    print(name, ok,'/',len(cases))
    for b in bad[:6]: print('   ',b)
""}

