use crate::log;

/// A field selector range: inclusive `[low, high]`, `usize::MAX` for an open high end.
pub type Range = (usize, usize);

pub const OPEN: usize = usize::MAX;

/// Parse a comma separated field spec like `1,2-,-5,2-5`.
pub fn parse_spec(spec: &str) -> Result<Vec<Range>, String> {
    let mut out = Vec::new();
    for part in spec.split(',') {
        out.push(parse_part(part)?);
    }
    Ok(out)
}

fn fail(msg: &str) -> String {
    format!("Failed to parse field: {}", msg)
}

fn numbered(n: usize) -> String {
    format!("Fields and positions are numbered from 1: {}", n)
}

fn parse_part(part: &str) -> Result<Range, String> {
    let stripped = part.strip_prefix('-').unwrap_or(part);
    let pieces: Vec<&str> = part.split('-').collect();
    if pieces.len() > 2 {
        return Err(fail(stripped));
    }
    if pieces.len() == 1 {
        let a = pieces[0];
        if a.is_empty() {
            return Err(fail(stripped));
        }
        let n = a
            .parse::<usize>()
            .map_err(|_| fail(stripped))?;
        if n == 0 {
            return Err(numbered(n));
        }
        return Ok((n, n));
    }
    let (a, b) = (pieces[0], pieces[1]);
    if a.is_empty() && b.is_empty() {
        return Err(fail(stripped));
    }
    let low = if a.is_empty() {
        None
    } else {
        Some(a.parse::<usize>().map_err(|_| fail(stripped))?)
    };
    let high = if b.is_empty() {
        None
    } else {
        Some(b.parse::<usize>().map_err(|_| fail(stripped))?)
    };
    if let Some(l) = low {
        if l == 0 {
            return Err(numbered(l));
        }
    }
    if let (Some(l), Some(h)) = (low, high) {
        if h < l {
            return Err(format!(
                "High end of range less than low end of range: {}",
                part
            ));
        }
    }
    if let Some(h) = high {
        if h == 0 {
            return Err(numbered(h));
        }
    }
    Ok((low.unwrap_or(1), high.unwrap_or(OPEN)))
}

/// Expand a set of ranges for a line with `n` fields, returning field indices in
/// spec order with duplicates removed (only the first occurrence is kept).
pub fn expand(ranges: &[Range], n: usize, out: &mut Vec<usize>) {
    for &(low, high) in ranges {
        let hi = if high == OPEN { n } else { high.min(n) };
        let lo = low.min(n.saturating_add(1));
        if lo == 0 {
            continue;
        }
        let mut i = lo;
        while i <= hi {
            out.push(i);
            i += 1;
        }
    }
}

/// Header matching helpers.
pub enum HeaderSel {
    Literal(String),
    Regex(regex::Regex),
}

impl HeaderSel {
    pub fn build(s: &str, is_regex: bool) -> Result<HeaderSel, regex::Error> {
        if is_regex {
            Ok(HeaderSel::Regex(regex::Regex::new(s)?))
        } else {
            Ok(HeaderSel::Literal(s.to_string()))
        }
    }
    pub fn matches(&self, header: &str) -> bool {
        match self {
            HeaderSel::Literal(s) => header == s,
            HeaderSel::Regex(r) => r.is_match(header),
        }
    }
}
