    }

    /// Split `line` (including its terminator) into field boundaries.
    /// Returns a Vec of (start, end) byte offsets into `line`.
    pub fn field_boundaries(&mut self, line: &[u8], content_len: usize) -> Vec<(usize, usize)> {
