            self.buf.extend_from_slice(&buf[written..written + take]);
            written += take;
            if self.buf.len() == BLOCK_UNCOMPRESSED {
                let data = std::mem::take(&mut self.buf);
                self.flush_block(&data, false)?;
            }
        }
        Ok(buf.len())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

fn crc32(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256u32 {
        let mut c = i;
        for _ in 0..8 {
            c = if c & 1 != 0 { 0xEDB88320 ^ (c >> 1) } else { c >> 1 };
        }
        table[i as usize] = c;
    }
    let mut crc: u32 = 0xFFFF_FFFF;
    for &b in data {
        crc = table[((crc ^ b as u32) & 0xff) as usize] ^ (crc >> 8);
    }
    !crc
}

/// Known decompressors keyed by file extension.
pub fn decompressor_for(path: &str) -> Option<Vec<String>> {
    let lower_ext = |p: &str| -> Option<String> {
        p.rsplit_once('.').map(|(_, e)| e.to_string())
    };
    match lower_ext(path).as_deref() {
        Some("Z") | Some("tgz") => Some(vec!["gzip".into(), "-d".into(), "-c".into()]),
        Some("bz2") => Some(vec!["bzip2".into(), "-d".into(), "-c".into()]),
        Some("xz") => Some(vec!["xz".into(), "-d".into(), "-c".into()]),
        Some("lzma") => Some(vec!["xz".into(), "--format=lzma".into(), "-d".into(), "-c".into()]),
        _ => None,
    }
}

/// Read `path`'s contents, decompressing it if possible.
/// Returns Ok(None) when no decompressor applies (plain read).
pub fn read_decompressed(path: &str) -> std::io::Result<Vec<u8>> {
    let mut buf = Vec::new();
    let f = std::fs::File::open(path)?;
    let mut br = std::io::BufReader::new(f);
    br.read_to_end(&mut buf)?;
    if crate::looks_like_gz(&buf) || path.ends_with(".gz") {
        let mut d = flate2::read::MultiGzDecoder::new(&buf[..]);
        let mut out = Vec::new();
        d.read_to_end(&mut out)?;
        return Ok(out);
    }
    Ok(buf)
}
