//! gzip helpers. `-Z` writes a "blocked gzip" stream: a sequence of independent
//! gzip members, each carrying an `BC` extra field with the size of the block so
//! that readers can seek, followed by an empty terminating member.

use std::io::{Read, Write};

/// Maximum number of uncompressed bytes per gzip member.
const BLOCK_UNCOMPRESSED: usize = 65280;

fn xfl_for_level(level: u32) -> u8 {
    match level {
        0..=1 => 4,
        9..=u32::MAX => 2,
        _ => 0,
    }
}

/// Wrap `inner` so that everything written is turned into a blocked gzip stream.
pub struct BlockGzWriter<W: Write> {
    inner: W,
    level: u32,
    buf: Vec<u8>,
}

impl<W: Write> BlockGzWriter<W> {
    pub fn new(inner: W, level: u32) -> Self {
        BlockGzWriter { inner, level, buf: Vec::new() }
    }

    fn flush_block(&mut self, data: &[u8], empty: bool) -> std::io::Result<()> {
        let mut body: Vec<u8> = Vec::with_capacity(data.len() + 64);
        let mut enc = flate2::write::DeflateEncoder::new(&mut body, flate2::Compression::new(self.level));
        enc.write_all(data)?;
        enc.finish()?;
        let crc = crc32(data);
        let member_len = 18 + body.len() + 8;
        let mut hdr = Vec::with_capacity(18);
        hdr.extend_from_slice(&[0x1f, 0x8b, 0x08, 0x04, 0, 0, 0, 0, xfl_for_level(self.level), 0xff]);
        let v = (member_len - 1) as u16;
        hdr.extend_from_slice(&[6, 0, b'B', b'C', (v & 0xff) as u8, (v >> 8) as u8]);
        self.inner.write_all(&hdr)?;
        self.inner.write_all(&body)?;
        self.inner.write_all(&crc.to_le_bytes())?;
        self.inner.write_all(&(data.len() as u32).to_le_bytes())?;
        Ok(())
    }

    pub fn finish(mut self) -> std::io::Result<W> {
        if !self.buf.is_empty() {
            let data = std::mem::take(&mut self.buf);
            self.flush_block(&data, false)?;
        }
        self.flush_block(&[], true)?;
        self.inner.flush()?;
        Ok(self.inner)
    }
}

impl<W: Write> Write for BlockGzWriter<W> {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        let mut written = 0;
        while written < buf.len() {
            let room = BLOCK_UNCOMPRESSED - self.buf.len();
            let take = buf.len() - written.min(buf.len());
            let take = take.min(room);
            self.buf.extend_from_slice(&buf[written..written + take]);
            written += take;
            if self.buf.len() == BLOCK_UNCOMPRESSED {
                let data = std::mem::take(&mut self.buf);
                self.flush_block(&data, false)?;
            }
        }
        Ok(buf.len())
    }
    fn flush(&mut self) -> std::io::Result<()> {
        Ok(())
    }
}

