        None => None,
    };

    let f_spec = match &a.fields {
        Some(s) => match fields::parse_spec(s) {
            Ok(v) => Some(v),
            Err(e) => {
                log::error(&e);
                return 1;
            }
        },
        None => None,
    };
    let e_spec = match &a.exclude {
        Some(s) => match fields::parse_spec(s) {
            Ok(v) => Some(v),
            Err(e) => {
                log::error(&e);
                return 1;
            }
        },
        None => None,
    };

    let mut header_sels: Vec<fields::HeaderSel> = Vec::new();
    for s in &a.header_field {
        match fields::HeaderSel::build(s, a.header_is_regex) {
            Ok(h) => header_sels.push(h),
            Err(e) => {
                log::error(&e.to_string());
                return 1;
            }
        }
    }
    let mut excl_sels: Vec<fields::HeaderSel> = Vec::new();
    for s in &a.exclude_header {
        match fields::HeaderSel::build(s, a.header_is_regex) {
            Ok(h) => excl_sels.push(h),
            Err(e) => {
                log::error(&e.to_string());
                return 1;
            }
        }
    }

    let delim = build_delim(&a.delimiter, a.delim_is_literal);
    let out_delim: Vec<u8> = if a.use_input_delim && a.delim_is_literal && a.output_delimiter_given == 0 {
        a.delimiter.clone().into_bytes()
    } else {
        a.output_delimiter.clone().into_bytes()
    };

    let w: Box<dyn Write> = match out_file {
        Some(f) => Box::new(f),
        None => Box::new(std::io::stdout()),
    };
    let out = if a.try_compress {
        Out { w: Box::new(compress::BlockGzWriter::new(w, a.compression_level)), buf: Vec::new(), limit: CHUNK }
    } else {
        Out { w, buf: Vec::new(), limit: CHUNK }
    };

    let mut state = State {
        select: Select {
            has_f: f_spec.is_some(),
            has_fspec: f_spec.is_some(),
            f_spec: f_spec.unwrap_or_default(),
            f_groups: Vec::new(),
            e_spec: e_spec.unwrap_or_default(),
            has_e: e_spec.is_some(),
            has_E: !excl_sels.is_empty(),
            E_groups: Vec::new(),
            has_F: !header_sels.is_empty(),
        },
        header_sels,
        excl_sels,
        delim,
        out_delim,
        out,
        crlf: a.crlf,
        try_decompress: a.try_decompress,
        err: false,
    };

    if a.input.is_empty() {
        if let Err(e) = crate::process_stream(&mut state, None, "<stdin>") {
            return finish_err(state, e);
        }
    } else {
        for path in &a.input {
            if let Err(e) = crate::process_stream(&mut state, Some(path), path) {
                return finish_err(state, e);
            }
        }
    }
    state.out.flush();
    if state.err {
        1
    } else {
        0
    }
}

fn finish_err(mut s: State, e: ParseErr) -> i32 {
    match e {
        ParseErr::Fatal(msg) => {
            log::error(&msg);
        }
    }
    let _ = &mut s;
    1
}

fn report_anyhow(msg: &str, cause: &str) {
    eprintln!("Error: {}\n\nCaused by:\n    {}", msg, cause);
}

struct State {
    select: Select,
    header_sels: Vec<fields::HeaderSel>,
    excl_sels: Vec<fields::HeaderSel>,
    delim: Delim,
    out_delim: Vec<u8>,
    out: Out,
    crlf: bool,
    try_decompress: bool,
    err: bool,
}

impl State {
    /// Split the raw line into field byte ranges (relative to the line slice).
    fn boundaries(&mut self, line: &[u8], content_len: usize, first: bool) -> Vec<(usize, usize)> {
        match &self.delim {
            Delim::Single(d) => {
                let mut p = lib::single_byte_delim_parser::SingleByteDelimParser::new(*d, self.crlf);
                p.first = first;
                p.field_boundaries(line, content_len)
            }
            Delim::Multi(v) => {
                let p = lib::multi_byte_delim_parser::MultiByteDelimParser::new(v.clone());
                p.field_boundaries(line, content_len)
            }
            Delim::Regex(re) => {
                let p = lib::regex_delim_parser::RegexDelimParser::new(re.clone());
                p.field_boundaries(line, content_len)
            }
        }
    }
}

fn process_stream(s: &mut State, path: Option<&str>, display: &str) -> Result<(), ParseErr> {
    // Determine the data source, decompressing when requested and possible.
    let mut data: Vec<u8> = Vec::new();
    match path {
        None => {
            std::io::stdin().read_to_end(&mut data).map_err(|e| ParseErr::Fatal(e.to_string()))?;
        }
        Some(p) => {
            let ext = crate::ext_of(p);
            let mut handled = false;
            if s.try_decompress {
                if ext.as_deref() == Some("gz") {
                    let mut buf = Vec::new();
                    let f = std::fs::File::open(p).map_err(|e| ParseErr::Fatal(e.to_string()))?;
                    let mut br = std::io::BufReader::new(f);
                    br.read_to_end(&mut buf).map_err(|e| ParseErr::Fatal(e.to_string()))?;
                    let mut d = flate2::read::MultiGzDecoder::new(&buf[..]);
                    match d.read_to_end(&mut data) {
                        Ok(_) => handled = true,
                        Err(e) => return Err(ParseErr::Fatal(e.to_string())),
                    }
                } else if let Some(cmd) = compress::decompressor_for(p) {
                    match crate::run_decompressor(&cmd, p) {
                        Ok(v) => {
                            data = v;
                            handled = true;
                        }
                        Err(msg) => return Err(ParseErr::Fatal(msg)),
                    }
                }
            }
            if !handled {
                let f = std::fs::File::open(p).map_err(|e| ParseErr::Fatal(e.to_string()))?;
                let mut br = std::io::BufReader::new(f);
                br.read_to_end(&mut data).map_err(|e| ParseErr::Fatal(e.to_string()))?;
            }
        }
    }

    process_data(s, &data, path.is_some())
}

fn ext_of(p: &str) -> Option<String> {
    p.rsplit_once('.').map(|(_, e)| e.to_string())
}

fn run_decompressor(cmd: &[String], path: &str) -> Result<Vec<u8>, ParseErr> {
    use std::process::{Command, Stdio};
    let program = &cmd[0];
    let child = Command::new(program)
        .args(&cmd[1..])
        .arg(path)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn();
    match child {
        Err(_) => Err(ParseErr::Fatal("".into())),
        Ok(mut c) => {
            let mut out = Vec::new();
            if let Some(mut so) = c.stdout.take() {
                let _ = so.read_to_end(&mut out);
            }
            let mut errbuf = Vec::new();
            if let Some(mut se) = c.stderr.take() {
                let _ = se.read_to_end(&mut errbuf);
            }
            match c.wait() {
                Ok(st) if st.success() => Ok(out),
                _ => {
                    let text = String::from_utf8_lossy(&errbuf).to_string();
                    let mut msg = String::new();
                    msg.push('\n');
                    msg.push_str("    ");
                    msg.push_str(&"-".repeat(79));
                    for line in text.trim_end_matches('\n').split('\n') {
                        msg.push_str("\n    ");
                        msg.push_str(line);
                    }
                    msg.push_str("\n    ");
                    msg.push_str(&"-".repeat(79));
                    Err(ParseErr::Fatal(msg))
                }
            }
        }
    }
}

fn process_data(s: &mut State, data: &[u8], from_file: bool) -> Result<(), ParseErr> {
    let mut pos = 0usize;
    let mut first_line = true;
    let mut header_done = !s.select.has_F;
    let mut ehdr_done = !s.select.has_E;
    while pos < data.len() {
        // Find the end of the last complete line in the data.
        let last_nl = data[pos..].iter().rposition(|&b| b == b'\n').map(|i| pos + i);
        match last_nl {
            Some(nl) => {
                let end = nl + 1;
                let chunk = &data[pos..end];
                process_chunk(s, chunk, &mut first_line, &mut header_done, &mut ehdr_done, false)?;
                pos = end;
            }
            None => {
                // No newline at all: this is either a very long line still being
                // accumulated, or the tail of the input.
                break;
            }
        }
    }
    if pos < data.len() {
        let tail = &data[pos..];
        if tail.ends_with(b"\n") {
            process_chunk(s, tail, &mut first_line, &mut header_done, &mut ehdr_done, false)?;
        } else if s.crlf {
            process_chunk(s, tail, &mut first_line, &mut header_done, &mut ehdr_done, true)?;
        } else {
            return Err(ParseErr::Fatal("invalid data".into()));
        }
    }
    s.out.flush();
    Ok(())
}

fn process_chunk(
    s: &mut State,
    chunk: &[u8],
    first_line: &mut bool,
    header_done: &mut bool,
    ehdr_done: &mut bool,
    partial: bool,
) -> Result<(), ParseErr> {
    let mut start = 0usize;
    let mut idx = 0usize;
    while idx < chunk.len() {
        if chunk[idx] == b'\n' {
            let line = &chunk[start..=idx];
            process_line(s, line, first_line, header_done, ehdr_done, false)?;
            start = idx + 1;
        }
        idx += 1;
    }
    if partial && start < chunk.len() {
        process_line(s, &chunk[start..], first_line, header_done, ehdr_done, true)?;
    }
    Ok(())
}

fn process_line(
    s: &mut State,
    line: &[u8],
    first_line: &mut bool,
    header_done: &mut bool,
    ehdr_done: &mut bool,
    partial: bool,
) -> Result<(), ParseErr> {
    // Work out the content slice: everything up to the line terminator.
    let content_len = if partial {
        line.len()
    } else if s.crlf {
        if line.len() >= 2 && line[line.len() - 2] == b'\r' {
            line.len() - 2
        } else {
            line.len()
        }
    } else {
        line.len() - 1
    };
    let content = &line[..content_len];

    // Resolve header selectors on the first line.
    if !*header_done {
        *header_done = true;
        let hdrs = split_header_names(s, content);
        let mut groups: Vec<Vec<usize>> = Vec::new();
        for sel in &s.header_sels {
            let mut g = Vec::new();
            for (i, h) in hdrs.iter().enumerate() {
                if sel.matches(h) {
                    g.push(i + 1);
                }
            }
            groups.push(g);
        }
        if groups.iter().all(|g| g.is_empty()) {
            return Err(ParseErr::Fatal("No headers matched".into()));
        }
        for (i, g) in groups.iter().enumerate() {
            if g.is_empty() {
                let spec = &s.header_sels[i];
                let name = match spec {
                    fields::HeaderSel::Literal(s) => s.clone(),
                    fields::HeaderSel::Regex(r) => r.as_str().to_string(),
                };
                return Err(ParseErr::Fatal(format!("Header not found: {}", name)));
            }
        }
        s.select.f_groups = groups;
    }
    if !*ehdr_done {
        *ehdr_done = true;
        let hdrs = split_header_names(s, content);
        let mut groups: Vec<Vec<usize>> = Vec::new();
        for sel in &s.excl_sels {
            let mut g = Vec::new();
            for (i, h) in hdrs.iter().enumerate() {
                if sel.matches(h) {
                    g.push(i + 1);
                }
            }
            groups.push(g);
        }
        s.select.E_groups = groups;
    }

    let bounds = s.boundaries(line, content_len, *first_line);
    *first_line = false;

    // Count of fields in this line.
    let nfields = bounds.len();
    let mut selected: Vec<usize> = Vec::new();
    s.select.output_fields(nfields, &mut selected);

    let mut buf: Vec<u8> = Vec::new();
    for (i, &f) in selected.iter().enumerate() {
        if i > 0 {
            buf.extend_from_slice(&s.out_delim);
        }
        if f >= 1 && f <= nfields {
            let (a, b) = bounds[f - 1];
            buf.extend_from_slice(&content[a..b]);
        }
    }
    let nl: &[u8] = if s.crlf { b"\r\n" } else { b"\n" };
    buf.extend_from_slice(nl);
    s.out.push(&buf);
    Ok(())
}

fn split_header_names(s: &mut State, content: &[u8]) -> Vec<String> {
    let bounds = s.boundaries(content, content.len(), false);
    bounds
        .iter()
        .map(|&(a, b)| String::from_utf8_lossy(&content[a..b]).to_string())
        .collect()
}
