//! Parser for a single byte literal delimiter.
//!
//! Splitting a line on a single byte is the fast path: the field boundaries can
//! be found with a simple scan and no regex engine has to be involved. This
//! module also reproduces a quirk of the original binary, which panics when the
//! very first line of the input begins with the delimiter byte and the output
//! field list starts with field one.

/// A parser for lines delimited by a single byte.
pub struct SingleByteDelimParser {
    /// The delimiter byte.
    pub delim: u8,
    /// Whether CRLF line terminators are in use.
    pub crlf: bool,
}

impl SingleByteDelimParser {
    /// Build a parser for `delim`.
    pub fn new(delim: u8, crlf: bool) -> Self {
        SingleByteDelimParser { delim, crlf }
    }

    /// Return the field boundaries of `line`.
    ///
    /// `line` includes the line terminator, while `content_len` is the number of
    /// bytes that belong to the fields themselves. The returned offsets are
    /// relative to the start of `line`, as inclusive/exclusive pairs.
    pub fn field_boundaries(&self, line: &[u8], content_len: usize) -> Vec<(usize, usize)> {
        let mut bounds: Vec<(usize, usize)> = Vec::new();
        let mut start = 0usize;
        for i in 0..content_len {
            if line[i] == self.delim {
                bounds.push((start, i));
                start = i + 1;
            }
        }
        bounds.push((start, content_len));
        bounds
    }

    /// Number of fields the line contains, counting empty fields.
    ///
    /// This is simply the number of delimiter occurrences plus one, which is
    /// (the field count) so that it can be used for the position map as well.
    ///
    /// Exactly what the boundary list returned by `field_boundaries` has.
    pub fn field_count(&self, line: &[u8], content_len: usize) -> usize {
        let mut n = 1usize;
        for i in 0..content_len {
            if line[i] == self.delim {
                n += 1;
            }
        }
        n
    }

    /// True when the line begins with the delimiter byte.
    ///
    /// The original binary indexed the line with a value that underflows when
    /// the very first line of the input begins with the delimiter byte. That
    /// makes it abort with the panic reproduced below, including its exact
    /// source location, so that the two binaries behave in the same way.
    pub fn starts_with_delim(&self, line: &[u8], content_len: usize) -> bool {
        !self.crlf && content_len > 0 && line[0] == self.delim
    }

    /// Panics when the first line of the input begins with the delimiter byte
    /// and the output field list starts with field one. The original binary did
    /// this unconditionally in that situation, so the behaviour is mirrored
    /// here, down to the panic message and the source location it reports.
    pub fn maybe_first_line_panic(&self, line: &[u8], content_len: usize, field1_first: bool) {
