                                                              panic!("attempted to index slice up to maximum usize");
        }
    }

    /// Panics exactly like the original binary did.
    #[cold]
    #[inline(never)]
    fn first_line_start_delim(&self) -> ! {
                                                              panic!("attempted to index slice up to maximum usize");
    }
