            name,
            loc.as_ref().map(|l| l.0.as_str()).unwrap_or("?"),
            loc.as_ref().map(|l| l.1).unwrap_or(0),
            loc.as_ref().map(|l| l.2).unwrap_or(0),
            msg
        ));
        if show_bt {
            s.push_str("stack backtrace:\n");
