/// The line parser in use.
enum Delim {
    Single(lib::single_byte_delim_parser::SingleByteDelimParser),
    Multi(lib::multi_byte_delim_parser::MultiByteDelimParser),
    Regex(lib::regex_delim_parser::RegexDelimParser),
}

fn build_delim(d: &str, literal: bool, crlf: bool) -> Delim {
    if literal {
        let b = d.as_bytes().to_vec();
        if b.len() == 1 {
            Delim::Single(lib::single_byte_delim_parser::SingleByteDelimParser::new(b[0], crlf))
        } else {
            Delim::Multi(lib::multi_byte_delim_parser::MultiByteDelimParser::new(b))
        }
    } else {
        match regex::Regex::new(d) {
            Ok(re) => Delim::Regex(lib::regex_delim_parser::RegexDelimParser::new(re)),
            Err(_) => Delim::Multi(lib::multi_byte_delim_parser::MultiByteDelimParser::new(d.as_bytes().to_vec())),
        }
    }
}

/// Buffered sink. Its contents are dropped when the run fails, mirroring the
/// original behaviour of losing unflushed output on error.
struct Out {
    w: Box<dyn Write>,
    buf: Vec<u8>,
    limit: usize,
}

impl Out {
    fn push(&mut self, data: &[u8]) {
        self.buf.extend_from_slice(data);
        if self.buf.len() >= self.limit {
            let b = std::mem::take(&mut self.buf);
            let _ = self.w.write_all(&b);
        }
    }
    fn flush(&mut self) {
        if !self.buf.is_empty() {
            let b = std::mem::take(&mut self.buf);
            let _ = self.w.write_all(&b);
        }
        let _ = self.w.flush();
    }
}

/// Holds everything needed to turn a line into the selected output columns.
struct Select {
    f_spec: Vec<fields::Range>,
    f_groups: Vec<Vec<usize>>,
    e_spec: Vec<fields::Range>,
    E_groups: Vec<Vec<usize>>,
    has_f: bool,
    has_e: bool,
    has_F: bool,
    has_E: bool,
}

impl Select {
    fn output_fields(&self, n: usize, out: &mut Vec<usize>) {
        out.clear();
        if self.has_f {
            fields::expand(&self.f_spec, n, out);
            if self.has_F {
                for g in &self.f_groups {
                    for &x in g {
                        if !out.contains(&x) {
                            let p = if out.is_empty() {
                                0
                            } else if x <= out[0] {
                                0
                            } else {
                                1
                            };
                            let p = p.min(out.len());
                            out.insert(p, x);
                        }
                    }
                }
            }
        } else if self.has_F {
            for g in &self.f_groups {
                for &x in g {
                    if !out.contains(&x) {
                        out.push(x);
                    }
                }
            }
        } else {
            for i in 1..=n {
                out.push(i);
            }
        }
        if self.has_e {
            let mut ex: Vec<usize> = Vec::new();
            fields::expand(&self.e_spec, n, &mut ex);
            out.retain(|&x| !ex.contains(&x));
        }
        if self.has_E {
            let mut ex: Vec<usize> = Vec::new();
            for g in &self.E_groups {
                ex.extend_from_slice(g);
            }
            out.retain(|&x| !ex.contains(&x));
        }
    }
}

/// Fatal errors abort the whole run with exit status one.
enum ParseErr {
    Fatal(String),
}

struct State {
    select: Select,
    header_sels: Vec<fields::HeaderSel>,
    excl_sels: Vec<fields::HeaderSel>,
    delim: Delim,
    out_delim: Vec<u8>,
    out: Out,
    crlf: bool,
    try_decompress: bool,
}

impl State {
    /// Split the raw line into field byte ranges (relative to the line slice).
    fn boundaries(&self, line: &[u8], content_len: usize) -> Vec<(usize, usize)> {
        match &self.delim {
            Delim::Single(p) => p.field_boundaries(line, content_len),
            Delim::Multi(p) => p.field_boundaries(line, content_len),
            Delim::Regex(p) => p.field_boundaries(line, content_len),
        }
    }

    /// Reproduce the original's panic for a leading delimiter on the first line.
    fn maybe_panic(&self, line: &[u8], content_len: usize, field1_first: bool) {
        if let Delim::Single(p) = &self.delim {
            p.maybe_first_line_panic(line, content_len, field1_first);
        }
    }

    fn header_names(&self, content: &[u8]) -> Vec<String> {
        let bounds = self.boundaries(content, content.len());
        bounds
            .iter()
            .map(|&(a, b)| String::from_utf8_lossy(&content[a..b]).to_string())
            .collect()
    }
}

fn report_anyhow(msg: &str, cause: &str) {
    eprintln!("Error: {}\n\nCaused by:\n    {}", msg, cause);
}

fn run() -> i32 {
    let a = args::parse_args();

    let out_file: Option<std::fs::File> = match &a.output {
        Some(p) => match std::fs::File::create(p) {
            Ok(f) => Some(f),
            Err(e) => {
                report_anyhow(&format!("Failed to open {} for writing.", p), &e.to_string());
                return 1;
            }
        },
        None => None,
    };

    let f_spec = match &a.fields {
        Some(s) => match fields::parse_spec(s) {
            Ok(v) => Some(v),
            Err(e) => {
                log::error(&e);
                return 1;
            }
        },
        None => None,
    };
    let e_spec = match &a.exclude {
        Some(s) => match fields::parse_spec(s) {
            Ok(v) => Some(v),
            Err(e) => {
                log::error(&e);
                return 1;
            }
        },
        None => None,
    };

    let mut header_sels: Vec<fields::HeaderSel> = Vec::new();
    for s in &a.header_field {
        match fields::HeaderSel::build(s, a.header_is_regex) {
            Ok(h) => header_sels.push(h),
            Err(e) => {
                log::error(&e.to_string());
                return 1;
            }
        }
    }
    let mut excl_sels: Vec<fields::HeaderSel> = Vec::new();
    for s in &a.exclude_header {
        match fields::HeaderSel::build(s, a.header_is_regex) {
            Ok(h) => excl_sels.push(h),
            Err(e) => {
                log::error(&e.to_string());
                return 1;
            }
        }
    }

    let delim = build_delim(&a.delimiter, a.delim_is_literal, a.crlf);
    let out_delim: Vec<u8> = if a.use_input_delim && a.delim_is_literal {
        a.delimiter.clone().into_bytes()
    } else {
        a.output_delimiter.clone().into_bytes()
    };

    let w: Box<dyn Write> = match out_file {
        Some(f) => Box::new(f),
        None => Box::new(std::io::stdout()),
    };
    let out = if a.try_compress {
        Out { w: Box::new(compress::BlockGzWriter::new(w, a.compression_level)), buf: Vec::new(), limit: CHUNK }
    } else {
        Out { w, buf: Vec::new(), limit: CHUNK }
    };

    let mut state = State {
        select: Select {
            f_spec: f_spec.unwrap_or_default(),
            f_groups: Vec::new(),
            e_spec: e_spec.unwrap_or_default(),
            E_groups: Vec::new(),
            has_f: a.fields.is_some(),
            has_e: a.exclude.is_some(),
            has_F: !header_sels.is_empty(),
            has_E: !excl_sels.is_empty(),
        },
        header_sels,
        excl_sels,
        delim,
        out_delim,
        out,
        crlf: a.crlf,
        try_decompress: a.try_decompress,
    };

    if a.input.is_empty() {
        if let Err(e) = process_stream(&mut state, None) {
            return fatal(state, e);
        }
    } else {
        for path in &a.input {
            if let Err(e) = process_stream(&mut state, Some(path)) {
                return fatal(state, e);
            }
        }
    }
    state.out.flush();
    if state.had_error() {
        1
    } else {
        0
    }
}

fn fatal(s: State, e: ParseErr) -> i32 {
    match e {
        ParseErr::Fatal(msg) => log::error(&msg),
    }
    let mut s = s;
    s.out.flush_quiet();
    1
}

impl State {
    fn had_error(&self) -> bool {
        self.error_flag
    }
    fn set_error(&mut self) {
        self.error_flag = true;
    }
}

fn process_stream(s: &mut State, path: Option<&str>) -> Result<(), ParseErr> {
    let mut data: Vec<u8> = Vec::new();
    match path {
        None => {
            std::io::stdin().read_to_end(&mut data).map_err(|e| ParseErr::Fatal(e.to_string()))?;
        }
        Some(p) => {
            let ext = ext_of(p);
            let mut handled = false;
            if s.try_decompress {
                if ext.as_deref() == Some("gz") {
                    let mut buf = Vec::new();
                    let f = std::fs::File::open(p).map_err(|e| ParseErr::Fatal(e.to_string()))?;
                    let mut br = std::io::BufReader::new(f);
                    br.read_to_end(&mut buf).map_err(|e| ParseErr::Fatal(e.to_string()))?;
                    let mut d = flate2::read::MultiGzDecoder::new(&buf[..]);
                    match d.read_to_end(&mut data) {
                        Ok(_) => handled = true,
                        Err(e) => return Err(ParseErr::Fatal(e.to_string())),
                    }
                } else if let Some(cmd) = compress::decompressor_for(p) {
                    match run_decompressor(&cmd, p) {
                        Ok(v) => {
                            data = v;
                            handled = true;
                        }
                        Err(msg) => return Err(msg),
                    }
                }
            }
            if !handled {
                let f = std::fs::File::open(p).map_err(|e| ParseErr::Fatal(e.to_string()))?;
                let mut br = std::io::BufReader::new(f);
                br.read_to_end(&mut data).map_err(|e| ParseErr::Fatal(e.to_string()))?;
            }
        }
    }
    process_data(s, &data)
}

fn ext_of(p: &str) -> Option<String> {
    p.rsplit_once('.').map(|(_, e)| e.to_string())
}

fn run_decompressor(cmd: &[String], path: &str) -> Result<Vec<u8>, ParseErr> {
    use std::process::{Command, Stdio};
    let child = Command::new(&cmd[0])
        .args(&cmd[1..])
        .arg(path)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn();
    match child {
        Err(_) => Err(ParseErr::Fatal(String::new())),
        Ok(mut c) => {
            let mut out = Vec::new();
            if let Some(mut so) = c.stdout.take() {
                let _ = so.read_to_end(&mut out);
            }
            let mut errbuf = Vec::new();
            if let Some(mut se) = c.stderr.take() {
                let _ = se.read_to_end(&mut errbuf);
            }
            match c.wait() {
                Ok(st) if st.success() => Ok(out),
                _ => {
                    let text = String::from_utf8_lossy(&errbuf).to_string();
                    let mut msg = String::new();
                    msg.push('\n');
                    msg.push_str("    ");
                    msg.push_str(&"-".repeat(79));
                    for line in text.trim_end_matches('\n').split('\n') {
                        msg.push_str("\n    ");
                        msg.push_str(line);
                    }
                    msg.push_str("\n    ");
                    msg.push_str(&"-".repeat(79));
                    Err(ParseErr::Fatal(msg))
                }
            }
        }
    }
}

fn process_data(s: &mut State, data: &[u8]) -> Result<(), ParseErr> {
    let mut pos = 0usize;
    let mut first_line = true;
    let mut header_done = !s.select.has_F;
    let mut ehdr_done = !s.select.has_E;
    while pos < data.len() {
        let last_nl = data[pos..].iter().rposition(|&b| b == b'\n').map(|i| pos + i);
        match last_nl {
            Some(nl) => {
                let end = nl + 1;
                process_chunk(s, &data[pos..end], &mut first_line, &mut header_done, &mut ehdr_done, false)?;
                pos = end;
            }
            None => break,
        }
    }
    if pos < data.len() {
        let tail = &data[pos..];
        if tail.ends_with(b"\n") {
            process_chunk(s, tail, &mut first_line, &mut header_done, &mut ehdr_done, false)?;
        } else if s.crlf {
            process_chunk(s, tail, &mut first_line, &mut header_done, &mut ehdr_done, true)?;
        } else {
            return Err(ParseErr::Fatal("invalid data".into()));
        }
    }
    s.out.flush();
    Ok(())
}

fn process_chunk(
    s: &mut State,
    chunk: &[u8],
    first_line: &mut bool,
    header_done: &mut bool,
    ehdr_done: &mut bool,
    partial: bool,
) -> Result<(), ParseErr> {
    let mut start = 0usize;
    for i in 0..chunk.len() {
        if chunk[i] == b'\n' {
            let line = &chunk[start..=i];
            process_line(s, line, first_line, header_done, ehdr_done, false)?;
            start = i + 1;
        }
    }
    if partial && start < chunk.len() {
        process_line(s, &chunk[start..], first_line, header_done, ehdr_done, true)?;
    }
    Ok(())
}

fn process_line(
    s: &mut State,
    line: &[u8],
    first_line: &mut bool,
    header_done: &mut bool,
    ehdr_done: &mut bool,
    partial: bool,
) -> Result<(), ParseErr> {
    let content_len = if partial {
        line.len()
    } else if s.crlf {
        if line.len() >= 2 && line[line.len() - 2] == b'\r' {
