cases=[([int(c) for c in L.split(',')],x,out) for (L,x),out in d.items()]
def first_ge(L,x): return next((i for i,f in enumerate(L) if f>=x), len(L))
def count_lt(L,x): return sum(1 for f in L if f<x)
def zero_one(L,x): return 0 if (L and x<=L[0]) else 1
for name,fn in [('first_ge',first_ge),('count_lt',count_lt),('zero_one',zero_one)]:
    ok=0; bad=[]
    for L,x,out in cases:
        b=[f for f in L if f!=x]
        p=min(fn(L,x),len(b))
        pr=b[:p]+[x]+b[p:]
        if pr==out: ok+=1
        else: bad.append((L,x,out,pr))
    print(name, ok,'/',len(cases))
    if name=='first_ge':
        for bb in bad[:12]: print('   ',bb)
""}

