import json
d={eval(k):v for k,v in json.load(open('/tmp/ord_data.json')).items()}
cases=[([int(c) for c in L.split(',')],x,out) for (L,x),out in d.items()]
def is_asc(L): return all(L[i]<L[i+1] for i in range(len(L)-1))
def hybrid(L,x):
    if is_asc(L): return sum(1 for f in L if f<x)
    return 0 if (L and x<=L[0]) else 1
def zero_one(L,x): return 0 if (L and x<=L[0]) else 1
def hybrid2(L,x):
    if is_asc(L): return sum(1 for f in L if f<x)
    return 1 if (L and x>L[0]) else 0
for name,fn in [('zero_one',zero_one),('hybrid',hybrid),('hybrid2',hybrid2)]:
    ok=0;bad=[]
    for L,x,out in cases:
        b=[f for f in L if f!=x]
        p=min(fn(L,x),len(b))
        pr=b[:p]+[x]+b[p:]
        if pr==out: ok+=1
        else: bad.append((L,x,out,pr))
    print(name, ok,'/',len(cases))
    if name=='hybrid':
        for bb in bad[:8]: print('   ',bb)
""}

